      to: j.To || j.to || '',
      subject: j.Subject || j.subject || '',
      snippet: j.snippet || '',
      existingLabels: (j.labels || []).map(label => label.name || label.id),
      mimeType: j.payload?.mimeType || '',
      sizeEstimate: j.sizeEstimate || null,
      internalDate: j.internalDate || null
    }
  };
});

const emails = items.map(item => {
  const e = item.json;

  return {
    from: e.from,
    subject: e.subject,
    snippet: (e.snippet || '').slice(0, 300),
    existingLabels: e.existingLabels
  };
});

return [
  {
    json: {
      sample_size: emails.length,
      emails
    }
  }
];

const item = $input.first().json;
const proposal = item.output?.[0]?.content?.[0]?.text;

if (!proposal) {
  throw new Error('Could not find proposal at output[0].content[0].text');
}

const labels = proposal.labels_to_create || proposal.labels?.map(label => label.name) || [];

return [
  {
    json: {
      status: 'pending_approval',
      labels_to_create: labels,
      proposal_json: proposal,
      created_at: new Date().toISOString()
    }
  }
];

let labelsRaw = $input.first().json["Approved Labels"];
let labels;

if (typeof labelsRaw === 'string') {
  labels = JSON.parse(labelsRaw);
} else {
  labels = labelsRaw;
}

if (!Array.isArray(labels)) {
  throw new Error('Approved Labels must be a JSON array of label names');
}

const cleaned = labels
  .map(label => typeof label === 'string' ? label.trim() : label.name?.trim())
  .filter(Boolean);

if (!cleaned.includes('Needs Review')) {
  cleaned.push('Needs Review');
}

return [...new Set(cleaned)].map(labelName => ({ json: { labelName } }));

const createdLabels = $input.all().map(i => i.json);
const labelMap = {};

for (const label of createdLabels) {
  labelMap[label.name] = label.id;
}

return [
  {
    json: {
      labelMap,
      approvedLabels: Object.keys(labelMap)
    }
  }
];

const approvedLabels = $('Map Label Names to IDs').first().json.approvedLabels || [];

return items.map(item => {
  const j = item.json;

  return {
    json: {
      id: j.id,
      threadId: j.threadId,
      from: j.From || j.from || '',
      to: j.To || j.to || '',
      subject: j.Subject || j.subject || '',
      snippet: (j.snippet || '').slice(0, 500),
      existingLabels: (j.labels || []).map(label => label.name || label.id),
      approvedLabels
    }
  };
});

