const aiText = $json.output?.[0]?.content?.[0]?.text;

if (!aiText) {
  throw new Error('No AI text found');
}

const cleanText = (typeof aiText === 'string' ? aiText : JSON.stringify(aiText))
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const parsed = typeof aiText === 'string' ? JSON.parse(cleanText) : aiText;
const approvedLabels = $('Normalize Classification Emails').first().json.approvedLabels || [];

const validLabels = (parsed.labels || []).filter(label =>
  approvedLabels.includes(label)
);

return {
  json: {
    emailId: parsed.emailId || $json.id,
    labelsToApply: validLabels.length ? validLabels : ['Needs Review'],
    confidence: parsed.confidence || 0,
    reason: parsed.reason || '',
    originalAI: parsed
  }
};

return [
  {
    json: {
      processed_count: items.length,
      message: `${items.length} emails were labeled and marked AI_Reviewed.`
    }
  }
];
